validator:
function validate(input) {
  const [{ Friendship = [], Likes = [] }] = input;
  const pairs = new Set(), likes = new Set();
  for (const [a, b] of Friendship) {
    if (a === null || b === null) return 'Friendship ids may not be null.';
    if (a === b) return `User ${a} cannot be friends with themselves.`;
    if (pairs.has(`${a},${b}`)) return `Friendship (${a}, ${b}) appears twice.`;
    pairs.add(`${a},${b}`);
  }
  for (const [user, page] of Likes) {
    if (user === null || page === null) return 'Likes ids may not be null.';
    if (likes.has(`${user},${page}`)) return `Like (${user}, ${page}) appears twice.`;
    likes.add(`${user},${page}`);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const users = small ? 6 : 800, pages = small ? 7 : 300;
  const pairs = new Set(), likes = new Set(), Friendship = [], Likes = [];
  const friendRows = small ? Math.floor(rand() * 9) : 2000;
  for (let tries = 0; Friendship.length < friendRows && tries < friendRows * 5; tries++) {
    // Many friendships involve user 1, on either side, so the answer is rarely empty.
    let a = rand() < (small ? 0.5 : 0.1) ? 1 : 1 + Math.floor(rand() * users);
    let b = 1 + Math.floor(rand() * users);
    if (a === b) continue;
    if (rand() < 0.5) [a, b] = [b, a];
    if (pairs.has(`${a},${b}`)) continue;
    pairs.add(`${a},${b}`);
    Friendship.push([a, b]);
  }
  const likeRows = small ? Math.floor(rand() * 9) : 2000;
  for (let tries = 0; Likes.length < likeRows && tries < likeRows * 5; tries++) {
    const user = rand() < (small ? 0.25 : 0.05) ? 1 : 1 + Math.floor(rand() * users);
    const page = 10 + Math.floor(rand() * pages);
    if (likes.has(`${user},${page}`)) continue;
    likes.add(`${user},${page}`);
    Likes.push([user, page]);
  }
  return [{ Friendship, Likes }];
}
